// We'll process the file by finding each "id:" pattern and adding fields before "topics:"

let result = rawData;

// For each subject, find its topics array start and insert fields before it
for (const [subjectId, data] of Object.entries(subjectsData)) {
  // Find the position where "topics:" starts for this subject
  const idPattern = new RegExp(`(id:\\s*"${subjectId}"[\\s\\S]*?)(topics:)`, 'm');
  
  const newFields = `bibliography: ${JSON.stringify(data.bibliography, null, 10).replace(/\n/g, '\n          ')},
          methodology: ${JSON.stringify(data.methodology, null, 10).replace(/\n/g, '\n          ')},
          evaluation: ${JSON.stringify(data.evaluation, null, 10).replace(/\n/g, '\n          ')},
          objectives: ${JSON.stringify(data.objectives, null, 10).replace(/\n/g, '\n          ')},
          competencies: ${JSON.stringify(data.competencies, null, 10).replace(/\n/g, '\n          ')},
          partialExamples: ${JSON.stringify(data.partialExamples, null, 10).replace(/\n/g, '\n          ')},
          topics:`;
  
  result = result.replace(idPattern, `$1${newFields}`);
}

writeFileSync('src/data/curriculum.ts', result);
